<?php
require_once 'config.php'; require_login(); $pdo=db(); $page_title='Agents'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
try{if($action==='add'){$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Agent name is required.');$stmt=$pdo->prepare('INSERT INTO agents(name,phone,address,status) VALUES(?,?,?,?)');$stmt->execute([$name,trim($_POST['phone']??''),trim($_POST['address']??''),$_POST['status']==='Inactive'?'Inactive':'Active']);}
elseif($action==='status'){$stmt=$pdo->prepare("UPDATE agents SET status=IF(status='Active','Inactive','Active') WHERE id=?");$stmt->execute([(int)$_POST['id']]);} redirect('agents.php');
}catch(Throwable $ex){$error=$ex instanceof RuntimeException?$ex->getMessage():'Unable to save agent. Check the submitted information.';}}
$rows=$pdo->query("SELECT a.*, COALESCE((SELECT SUM(package_kg*quantity) FROM inventory_releases ir WHERE ir.agent_id=a.id),0) AS released_kg, COALESCE((SELECT SUM(package_kg*quantity) FROM deliveries d WHERE d.agent_id=a.id AND d.status <> 'Cancelled'),0) AS delivered_kg FROM agents a ORDER BY a.name")->fetchAll();
require 'includes/header.php'; ?><div class="shell"><?php require 'includes/sidebar.php'; ?><main class="main"><?php require 'includes/topbar.php'; ?><div class="content"><div class="page-heading"><div><div class="eyebrow">PEOPLE</div><h1>Agents</h1><p>Manage agent contacts and activity.</p></div></div>
<?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?>
<div class="panel"><div class="panel-head"><h2>Add an agent</h2></div><div class="panel-body"><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="field"><label>Agent name *</label><input name="name" required maxlength="120"></div><div class="field"><label>Phone number</label><input name="phone" maxlength="40"></div><div class="field"><label>Address</label><input name="address" maxlength="255"></div><div class="field"><label>Status</label><select name="status"><option>Active</option><option>Inactive</option></select></div><div class="field full"><button class="btn">＋ Save agent</button></div></form></div></div>
<div class="panel"><div class="panel-head"><h2>Agent directory <span class="badge"><?=count($rows)?> agents</span></h2></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>Released</th><th>Delivered</th><th>Estimated balance</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">No agents added yet.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><small><?=e($r['address']??'')?></small></td><td><?=e($r['phone']?:'—')?></td><td><?=number_format((float)$r['released_kg'],2)?> KG</td><td><?=number_format((float)$r['delivered_kg'],2)?> KG</td><td><?=number_format((float)$r['released_kg']-(float)$r['delivered_kg'],2)?> KG</td><td><span class="badge <?=$r['status']==='Active'?'':'red'?>"><?=e($r['status'])?></span></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-secondary"><?= $r['status']==='Active'?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach;?></tbody></table></div></div>
</div><?php require 'includes/footer.php';?></main></div>
